const resolveMessageProject = `-- name: ResolveMessageProject :one
select c.project_id from messages m
join conversations c on c.id = m.conversation_id
where m.id = $1
`

func (q *Queries) ResolveMessageProject(ctx context.Context, id pgtype.UUID) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, resolveMessageProject, id)
	var project_id pgtype.UUID
	err := row.Scan(&project_id)
	return project_id, err
}

const searchMessagesInProject = `-- name: SearchMessagesInProject :many
select m.id, m.conversation_id, m.body, m.tags, m.silent, m.created_at, m.edited_at,
       m.author_user_id, m.author_agent_id, m.author_kind_snapshot,
       coalesce(u.name, a.name, nullif(m.author_name_snapshot, ''), '') as author_name,
       coalesce(u.avatar_key, a.avatar_key) as author_avatar
from messages m
join conversations c on c.id = m.conversation_id
left join users u on u.id = m.author_user_id
left join agents a on a.id = m.author_agent_id
where c.project_id = $1
  and m.deleted_at is null
  and not c.agents_blocked
  and m.body ilike '%' || $2 || '%'
order by m.created_at desc
limit $3
`

type SearchMessagesInProjectParams struct {
	ProjectID pgtype.UUID `json:"project_id"`
	Q         pgtype.Text `json:"q"`
	Lim       int32       `json:"lim"`
}

type SearchMessagesInProjectRow struct {
	ID                 pgtype.UUID        `json:"id"`
	ConversationID     pgtype.UUID        `json:"conversation_id"`
	Body               string             `json:"body"`
	Tags               []string           `json:"tags"`
	Silent             bool               `json:"silent"`
	CreatedAt          pgtype.Timestamptz `json:"created_at"`
	EditedAt           pgtype.Timestamptz `json:"edited_at"`
	AuthorUserID       pgtype.UUID        `json:"author_user_id"`
	AuthorAgentID      pgtype.UUID        `json:"author_agent_id"`
	AuthorKindSnapshot string             `json:"author_kind_snapshot"`
	AuthorName         string             `json:"author_name"`
	AuthorAvatar       pgtype.Text        `json:"author_avatar"`
}

func (q *Queries) SearchMessagesInProject(ctx context.Context, arg SearchMessagesInProjectParams) ([]SearchMessagesInProjectRow, error) {
	rows, err := q.db.Query(ctx, searchMessagesInProject, arg.ProjectID, arg.Q, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchMessagesInProjectRow{}
	for rows.Next() {
		var i SearchMessagesInProjectRow
		if err := rows.Scan(
			&i.ID,
			&i.ConversationID,
			&i.Body,
			&i.Tags,
			&i.Silent,
			&i.CreatedAt,
			&i.EditedAt,
			&i.AuthorUserID,
			&i.AuthorAgentID,
			&i.AuthorKindSnapshot,
			&i.AuthorName,
			&i.AuthorAvatar,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setMessageTags = `-- name: SetMessageTags :exec
update messages set tags = $1 where id = $2
`

type SetMessageTagsParams struct {
	Tags []string    `json:"tags"`
	ID   pgtype.UUID `json:"id"`
}

func (q *Queries) SetMessageTags(ctx context.Context, arg SetMessageTagsParams) error {
	_, err := q.db.Exec(ctx, setMessageTags, arg.Tags, arg.ID)
	return err
}

const unpinMessageAgent = `-- name: UnpinMessageAgent :one
update messages set pinned_at = null
where id = $1 and deleted_at is null
returning id, conversation_id
`

type UnpinMessageAgentRow struct {
	ID             pgtype.UUID `json:"id"`
	ConversationID pgtype.UUID `json:"conversation_id"`
}

func (q *Queries) UnpinMessageAgent(ctx context.Context, id pgtype.UUID) (UnpinMessageAgentRow, error) {
	row := q.db.QueryRow(ctx, unpinMessageAgent, id)
	var i UnpinMessageAgentRow
	err := row.Scan(&i.ID, &i.ConversationID)
	return i, err
}

const updateMessageBodyAgent = `-- name: UpdateMessageBodyAgent :one
update messages set body = $1, edited_at = now()
where id = $2
  and author_agent_id = $3
  and deleted_at is null
returning id
`

type UpdateMessageBodyAgentParams struct {
	Body          string      `json:"body"`
	ID            pgtype.UUID `json:"id"`
	AuthorAgentID pgtype.UUID `json:"author_agent_id"`
}

// agents may edit their own messages while no agent has read them
func (q *Queries) UpdateMessageBodyAgent(ctx context.Context, arg UpdateMessageBodyAgentParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, updateMessageBodyAgent, arg.Body, arg.ID, arg.AuthorAgentID)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}
